-- Goethe B2 content refresh (ADR-0025): the teacher replaced every Sprechen and Schreiben topic with new ones,
-- and removed Lesen and Hören from B2 (done in code, those are content-in-code features). This migration wipes
-- the old Goethe B2 Sprechen topics (with their practices, assessments and recordings) and Schreiben lessons
-- (with their drafts, submissions and feedback), then seeds the new content. telc and every other level are
-- untouched. IDs are deterministic (md5 of a stable key) so the migration is idempotent.

-- === Sprechen: remove the old Goethe B2 topics and everything recorded on them ===
-- The audio files in the private `speaking-recordings` bucket (storage.objects has no FK cascade) are removed
-- out-of-band via the Storage API, because the hosted Postgres blocks a direct DELETE on storage tables
-- ("Direct deletion from storage tables is not allowed. Use the Storage API instead."). The paths are read from
-- speaking_practices before this migration runs and deleted with `supabase storage rm` afterwards (see ADR-0025).
-- Deleting the topics cascades to speaking_practices and speaking_assessments (ADR-0009 FKs).
delete from public.speaking_topics where level = 'B2' and exam = 'goethe';

on conflict do nothing;

-- === Schreiben: replace the lessons of the two B2 units ===
-- Deleting the lessons cascades to exercises, and from there to writing_drafts, writing_submissions and
-- feedback (initial schema + ADR-0003 FKs). The two B2 units themselves are kept.
delete from public.lessons
where unit_id in (md5('zz:unit:b2:teil1')::uuid, md5('zz:unit:b2:teil2')::uuid);

-- Teil 1 – Forumsbeitrag (one per Dupla, position = Dupla number).
on conflict do nothing;

on conflict do nothing;

-- Teil 2 – formal E-Mail (one per Dupla, position = Dupla number).
on conflict do nothing;

on conflict do nothing;
