insert into public.exercises (id, lesson_id, prompt, min_words, max_words, task_type, guiding_points, recipient) values
  (md5('zz:exercise:b2v2:teil1:1')::uuid, md5('zz:lesson:b2v2:teil1:1')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Fahrrad statt Auto im Alltag“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Nutzung von Fahrrädern im Alltag.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie andere umweltfreundliche Fortbewegungsmittel.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:2')::uuid, md5('zz:lesson:b2v2:teil1:2')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Ästhetische Chirurgie“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu Schönheitsoperationen.', 'Begründen Sie, warum Sie dafür oder dagegen sind.', 'Nennen Sie andere Möglichkeiten, das eigene Selbstbewusstsein zu stärken.', 'Nennen Sie Vorteile dieser Möglichkeiten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:3')::uuid, md5('zz:lesson:b2v2:teil1:3')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Besuch von Festivals und Konzerten“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu großen Musikveranstaltungen.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie andere Möglichkeiten, Musik intensiv zu erleben.', 'Nennen Sie Vorteile dieser Möglichkeiten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:4')::uuid, md5('zz:lesson:b2v2:teil1:4')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Smartphones in der Freizeit“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur ständigen Handynutzung.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten der Freizeitgestaltung ohne digitale Geräte.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:5')::uuid, md5('zz:lesson:b2v2:teil1:5')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Schnappschüsse auf Instagram und Co. veröffentlichen“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum Teilen privater Fotos im Internet.', 'Begründen Sie Ihre Ansicht.', 'Nennen Sie andere Wege, Fotos sicher mit Freunden zu teilen.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:6')::uuid, md5('zz:lesson:b2v2:teil1:6')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Marketingprodukte und Werbung für Jugendliche“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu Werbung, die sich an Kinder richtet.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten, Kinder vor Werbeeinflüssen zu schützen.', 'Nennen Sie Vorteile dieser Maßnahmen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:7')::uuid, md5('zz:lesson:b2v2:teil1:7')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Brauchen wir wirklich so viele neue Dinge?“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum aktuellen Konsumverhalten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Alternativen zum ständigen Neukauf von Produkten.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:8')::uuid, md5('zz:lesson:b2v2:teil1:8')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Parks und Grünanlagen in der Metropole“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Wichtigkeit von Grünflächen in Städten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie andere Möglichkeiten zur Erholung in der Stadt.', 'Nennen Sie Vorteile dieser Möglichkeiten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:9')::uuid, md5('zz:lesson:b2v2:teil1:9')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Ökologischer Urlaub fernab vom Massentourismus“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum nachhaltigen Reisen.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie alternative Reiseziele in der eigenen Region.', 'Nennen Sie Vorteile dieser Ziele.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:10')::uuid, md5('zz:lesson:b2v2:teil1:10')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Verfallene Produkte im Supermarkt“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Verschwendung von Lebensmitteln.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten, das Wegwerfen von Lebensmitteln zu vermeiden.', 'Nennen Sie Vorteile dieser Möglichkeiten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:11')::uuid, md5('zz:lesson:b2v2:teil1:11')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „E-Scooter und Elektroautos als Lösung?“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Nutzung von E-Scootern und E-Autos.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie weitere umweltfreundliche Fortbewegungsmittel im Alltag.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:12')::uuid, md5('zz:lesson:b2v2:teil1:12')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Wie man dem Großstadtlärm entkommen kann“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Lärmbelastung in Städten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten der Lärmreduzierung im privaten Alltag.', 'Nennen Sie Vorteile dieser Maßnahmen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:13')::uuid, md5('zz:lesson:b2v2:teil1:13')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Schleichwerbung auf Social Media“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu Produktempfehlungen durch Influencer.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Alternativen, um sich verlässlich über Produkte zu informieren.', 'Nennen Sie Vorteile dieser Informationsquellen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:14')::uuid, md5('zz:lesson:b2v2:teil1:14')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Tipps gegen das Wegwerfen von Mahlzeiten“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Verwertung von Speiseresten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie praktische Alternativen zum Wegwerfen von übrigem Essen.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:15')::uuid, md5('zz:lesson:b2v2:teil1:15')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Urlaub im Nationalpark“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum Urlaub in Naturschutzgebieten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie andere Freizeitaktivitäten in der Natur.', 'Nennen Sie Vorteile dieser Aktivitäten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:16')::uuid, md5('zz:lesson:b2v2:teil1:16')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Freizeitangebote für gestresste Stadtbewohner“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum Angebot an Erholungsmöglichkeiten in Städten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Alternativen zur Erholung am Wochenende außerhalb der Stadt.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:17')::uuid, md5('zz:lesson:b2v2:teil1:17')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Warum Menschen so gerne auf Konzerte gehen“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu Live-Konzerten.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten, Musik zu Hause in guter Qualität zu genießen.', 'Nennen Sie Vorteile des Musikhörens zu Hause.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:18')::uuid, md5('zz:lesson:b2v2:teil1:18')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Ist der persönliche Kontakt durch Handys gefährdet?“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum Einfluss von Smartphones auf persönliche Beziehungen.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie Möglichkeiten, ohne Technik mit Freunden in Kontakt zu bleiben.', 'Nennen Sie Vorteile dieser Möglichkeiten.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:19')::uuid, md5('zz:lesson:b2v2:teil1:19')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Digitale Notizen statt Papier und Stift an der Uni“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Nutzung von Laptops im Unterricht.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie alternative Lernmethoden ohne digitale Geräte.', 'Nennen Sie Vorteile dieser analogen Methoden.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:20')::uuid, md5('zz:lesson:b2v2:teil1:20')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Gesundheitsprüfungen für ältere Autofahrer“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zu verpflichtenden Fahrtauglichkeitsprüfungen.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie alternative Fortbewegungsmittel für Senioren.', 'Nennen Sie Vorteile dieser Alternativen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:21')::uuid, md5('zz:lesson:b2v2:teil1:21')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Sicherheit vs. Privatsphäre auf der Straße“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zur Videoüberwachung im öffentlichen Raum.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie andere Maßnahmen für mehr Sicherheit in Städten.', 'Nennen Sie Vorteile dieser Maßnahmen.']::text[], null),
  (md5('zz:exercise:b2v2:teil1:22')::uuid, md5('zz:lesson:b2v2:teil1:22')::uuid, 'Sie schreiben einen Forumsbeitrag zum Thema „Fitnessstudios vs. Training zu Hause“.', 150, 180, 'forum_post', array['Äußern Sie Ihre Meinung zum Training in Fitnessstudios.', 'Begründen Sie Ihre Meinung.', 'Nennen Sie alternative Sportarten, die man im Freien ausüben kann.', 'Nennen Sie Vorteile dieser Sportarten.']::text[], null)
