insert into public.exercises (id, lesson_id, prompt, min_words, max_words, task_type, guiding_points, recipient) values
  (md5('zz:exercise:b2v2:teil2:1')::uuid, md5('zz:lesson:b2v2:teil2:1')::uuid, 'Sie haben für Ihre Studiengruppe eine historische Stadtführung gebucht. Aufgrund von Terminproblemen kann die Gruppe nicht teilnehmen. Schreiben Sie eine E-Mail an das Tourismusbüro (Frau Müller).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Entschuldigung für die Absage.', 'Kurze Erklärung, warum die Gruppe keine Zeit hat.', 'Bitte um einen neuen Termin in der nächsten Woche.']::text[], 'Frau Müller (Tourismusbüro)'),
  (md5('zz:exercise:b2v2:teil2:2')::uuid, md5('zz:lesson:b2v2:teil2:2')::uuid, 'Sie machen ein Praktikum in einer Firma und möchten dieses um einen Monat verlängern. Schreiben Sie eine E-Mail an den Personalleiter, Herrn Bauer.', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Beschreiben Sie, was Ihnen am Praktikum besonders gefällt.', 'Erklären Sie, warum eine Verlängerung auch für die Firma nützlich ist.', 'Bitten Sie um ein persönliches Gespräch.']::text[], 'Herrn Bauer (Personalleiter)'),
  (md5('zz:exercise:b2v2:teil2:3')::uuid, md5('zz:lesson:b2v2:teil2:3')::uuid, 'Sie haben das Empfehlungsschreiben Ihrer alten Firma verloren und brauchen dringend ein neues. Schreiben Sie eine E-Mail an die Personalabteilung (Frau Weber).', 100, 120, 'formal_email', array['Grund für Ihre Nachricht.', 'Entschuldigung für die Unannehmlichkeiten.', 'Erklärung, warum Sie das Dokument schnell benötigen.', 'Bitte um die Zusendung einer digitalen Kopie.']::text[], 'Frau Weber (Personalabteilung)'),
  (md5('zz:exercise:b2v2:teil2:4')::uuid, md5('zz:lesson:b2v2:teil2:4')::uuid, 'Sie standen im Stau und haben Ihr Bewerbungsgespräch verpasst. Schreiben Sie eine E-Mail an den HR-Manager, Herrn Schmidt.', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Entschuldigung für das Verpassen des Termins.', 'Detaillierte Erklärung Ihrer Situation.', 'Bitte um einen Ersatztermin.']::text[], 'Herrn Schmidt (HR-Manager)'),
  (md5('zz:exercise:b2v2:teil2:5')::uuid, md5('zz:lesson:b2v2:teil2:5')::uuid, 'Ihre Firma wechselt das Gebäude. Sie wurden beauftragt, den Transport der Büromöbel zu koordinieren. Schreiben Sie eine E-Mail an das Umzugsunternehmen (Frau Klein).', 100, 120, 'formal_email', array['Grund für die E-Mail.', 'Details zum Umzug (Datum und genaue Adresse).', 'Kurze Beschreibung der Möbelmenge.', 'Bitte um einen Kostenvoranschlag.']::text[], 'Frau Klein (Umzugsunternehmen)'),
  (md5('zz:exercise:b2v2:teil2:6')::uuid, md5('zz:lesson:b2v2:teil2:6')::uuid, 'Sie finden, dass wichtige Informationen im Büro oft nicht rechtzeitig weitergegeben werden. Schreiben Sie Ihrem Teamleiter, Herrn Wagner, einen Lösungsvorschlag.', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Beschreibung des aktuellen Kommunikationsproblems.', 'Erklärung der negativen Folgen für das Team.', 'Ein konkreter Lösungsvorschlag (z. B. wöchentliches Meeting).']::text[], 'Herrn Wagner (Teamleiter)'),
  (md5('zz:exercise:b2v2:teil2:7')::uuid, md5('zz:lesson:b2v2:teil2:7')::uuid, 'Sie möchten künftig zwei Tage pro Woche von zu Hause aus arbeiten. Schreiben Sie eine E-Mail an Ihre Abteilungsleiterin, Frau Lehmann.', 100, 120, 'formal_email', array['Grund für die Nachricht.', 'Erklärung, warum das Homeoffice für Sie wichtig ist (z. B. Fahrtzeit sparen).', 'Darstellung der Vorteile für die Firma.', 'Bitte um einen Termin zur Besprechung.']::text[], 'Frau Lehmann (Abteilungsleiterin)'),
  (md5('zz:exercise:b2v2:teil2:8')::uuid, md5('zz:lesson:b2v2:teil2:8')::uuid, 'Sie möchten vorschlagen, dass in Ihrer Abteilung weniger ausgedruckt wird. Schreiben Sie an den Geschäftsführer, Herrn Hofmann.', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Beschreibung der aktuellen Situation mit dem Papierverbrauch.', 'Vorstellung Ihres konkreten Konzepts zur Digitalisierung.', 'Vorschlag für die nächsten Schritte zur Umsetzung.']::text[], 'Herrn Hofmann (Geschäftsführer)'),
  (md5('zz:exercise:b2v2:teil2:9')::uuid, md5('zz:lesson:b2v2:teil2:9')::uuid, 'Sie möchten mit einer Kindergruppe die örtliche Bibliothek besuchen. Schreiben Sie eine E-Mail an die Bibliotheksleitung (Frau Richter).', 100, 120, 'formal_email', array['Grund für die Anfrage.', 'Informationen über die Gruppe (Alter und Anzahl der Kinder).', 'Gewünschte Themen oder Schwerpunkte für die Führung.', 'Bitte um konkrete Terminvorschläge.']::text[], 'Frau Richter (Bibliotheksleitung)'),
  (md5('zz:exercise:b2v2:teil2:10')::uuid, md5('zz:lesson:b2v2:teil2:10')::uuid, 'Sie lernen viel in Ihrem aktuellen Projekt und möchten länger in der Abteilung bleiben. Schreiben Sie an den Projektleiter, Herrn Wolf.', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Beschreibung, was Sie bisher Positives gelernt haben.', 'Begründung, warum die Verlängerung für beide Seiten sinnvoll ist.', 'Konkreter Vorschlag für den neuen Zeitraum.']::text[], 'Herrn Wolf (Projektleiter)'),
  (md5('zz:exercise:b2v2:teil2:11')::uuid, md5('zz:lesson:b2v2:teil2:11')::uuid, 'Es gibt Spannungen in Ihrer Arbeitsgruppe wegen der Urlaubsplanung. Schreiben Sie an die Abteilungsleiterin, Frau Schröder.', 100, 120, 'formal_email', array['Grund für die E-Mail.', 'Sachliche Beschreibung der Konfliktsituation im Team.', 'Ein eigener Vorschlag für eine gerechte Lösung.', 'Bitte um ein gemeinsames Meeting zur Klärung.']::text[], 'Frau Schröder (Abteilungsleiterin)'),
  (md5('zz:exercise:b2v2:teil2:12')::uuid, md5('zz:lesson:b2v2:teil2:12')::uuid, 'Sie haben das Zertifikat Ihres letzten Fortbildungskurses verlegt. Schreiben Sie an das Fortbildungsinstitut (Herrn Neumann).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Kurze Entschuldigung für Ihr Missgeschick.', 'Angabe Ihrer genauen Kursdaten zur schnellen Identifikation.', 'Frage nach den Bedingungen und Kosten für eine Neuausstellung.']::text[], 'Herrn Neumann (Fortbildungsinstitut)'),
  (md5('zz:exercise:b2v2:teil2:13')::uuid, md5('zz:lesson:b2v2:teil2:13')::uuid, 'Sie können leider doch nicht an der exklusiven Führung durch die neue Kunstausstellung teilnehmen. Schreiben Sie eine E-Mail an die Galerie (Frau Schwarz).', 100, 120, 'formal_email', array['Grund für Ihre Nachricht.', 'Entschuldigung für die kurzfristige Absage.', 'Kurze Erklärung, warum Sie verhindert sind.', 'Frage nach der Möglichkeit, die Führung auf ein anderes Datum umzubuchen.']::text[], 'Frau Schwarz (Galerie)'),
  (md5('zz:exercise:b2v2:teil2:14')::uuid, md5('zz:lesson:b2v2:teil2:14')::uuid, 'Ihr Team muss nächste Woche in ein anderes Stockwerk ziehen. Schreiben Sie eine E-Mail an die Hausverwaltung (Herrn Braun).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Genaue Angabe, wie viele Umzugskartons Sie benötigen.', 'Mitteilung des geplanten Zeitpunkts für den Transport.', 'Bitte um eine kurze Bestätigung.']::text[], 'Herrn Braun (Hausverwaltung)'),
  (md5('zz:exercise:b2v2:teil2:15')::uuid, md5('zz:lesson:b2v2:teil2:15')::uuid, 'Ihr Zug hat eine Panne, weshalb Sie zu spät zu Ihrem Job-Interview kommen werden. Schreiben Sie eine E-Mail an die Personalbeschaffung (Frau Zimmermann).', 100, 120, 'formal_email', array['Grund für die schnelle Nachricht.', 'Entschuldigung für die Verspätung.', 'Genaue Schätzung, wann Sie eintreffen werden.', 'Frage, ob das Interview später am selben Tag stattfinden kann.']::text[], 'Frau Zimmermann (Personalbeschaffung)'),
  (md5('zz:exercise:b2v2:teil2:16')::uuid, md5('zz:lesson:b2v2:teil2:16')::uuid, 'Beim Umzug ist Ihr wichtiges Abschlusszeugnis beschädigt worden. Schreiben Sie an das Studiensekretariat (Herrn Krüger).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Erklärung, wie das Dokument beschädigt wurde.', 'Angabe Ihrer persönlichen Daten (z. B. Matrikelnummer) zur Überprüfung.', 'Bitte um Zusendung eines neuen offiziellen Dokuments.']::text[], 'Herrn Krüger (Studiensekretariat)'),
  (md5('zz:exercise:b2v2:teil2:17')::uuid, md5('zz:lesson:b2v2:teil2:17')::uuid, 'Sie haben ein Konzept entwickelt, wie die Abteilung auf Papier verzichten kann. Schreiben Sie eine E-Mail an die Betriebsleitung (Frau Lange).', 100, 120, 'formal_email', array['Grund für die E-Mail.', 'Kurze Zusammenfassung Ihres neuen Konzepts.', 'Erklärung der finanziellen Vorteile für die Firma.', 'Bitte um einen Präsentationstermin.']::text[], 'Frau Lange (Betriebsleitung)'),
  (md5('zz:exercise:b2v2:teil2:18')::uuid, md5('zz:lesson:b2v2:teil2:18')::uuid, 'Sie haben sich für den Vortrag eines bekannten Autors angemeldet, sind aber krank geworden. Schreiben Sie an die Veranstaltungsorganisation (Herrn Schmitz).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Entschuldigung für die Absage.', 'Erklärung, dass Sie aus gesundheitlichen Gründen nicht teilnehmen können.', 'Frage, ob die Tickets zurückgegeben oder auf jemand anderen übertragen werden können.']::text[], 'Herrn Schmitz (Veranstaltungsorganisation)'),
  (md5('zz:exercise:b2v2:teil2:19')::uuid, md5('zz:lesson:b2v2:teil2:19')::uuid, 'Sie wollten ein Interview mit einer Autorin für die Schülerzeitung führen, müssen den Termin aber verschieben. Schreiben Sie an ihr Management (Frau Krause).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Entschuldigung für die Umstände.', 'Erklärung des Grundes für die Terminverschiebung.', 'Vorschlag von zwei neuen Terminen.']::text[], 'Frau Krause (Management)'),
  (md5('zz:exercise:b2v2:teil2:20')::uuid, md5('zz:lesson:b2v2:teil2:20')::uuid, 'Sie möchten ab dem nächsten Jahr nur noch halbtags arbeiten, um Zeit für eine Weiterbildung zu haben. Schreiben Sie an den Filialleiter (Herrn Meier).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Erklärung, warum Sie mehr freie Zeit benötigen.', 'Vorschlag, wie Ihre aktuellen Aufgaben im Team verteilt werden könnten.', 'Bitte um ein persönliches Gespräch.']::text[], 'Herrn Meier (Filialleiter)'),
  (md5('zz:exercise:b2v2:teil2:21')::uuid, md5('zz:lesson:b2v2:teil2:21')::uuid, 'Sie sammeln im Büro Kleidung für eine Hilfsorganisation. Schreiben Sie an die Verantwortliche der Organisation (Frau Schulze).', 100, 120, 'formal_email', array['Grund für die E-Mail.', 'Details zu den gesammelten Spenden (Art und Menge der Kleidung).', 'Frage nach dem idealen Zeitpunkt für die Übergabe.', 'Bitte um eine kurze Bestätigung.']::text[], 'Frau Schulze (Hilfsorganisation)'),
  (md5('zz:exercise:b2v2:teil2:22')::uuid, md5('zz:lesson:b2v2:teil2:22')::uuid, 'Sie ziehen in eine andere Stadt und müssen Ihre Mitgliedschaft im Sportverein vorzeitig kündigen. Schreiben Sie an die Mitgliederverwaltung (Herrn Becker).', 100, 120, 'formal_email', array['Grund für das Schreiben.', 'Erklärung der aktuellen Situation (Umzug).', 'Angabe des gewünschten Kündigungsdatums.', 'Bitte um eine schriftliche Kündigungsbestätigung.']::text[], 'Herrn Becker (Mitgliederverwaltung)')
